/// <summary>
/// PricingAttribute of table <c>CustTable</c> field CustTradingPartnerCode.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustTableCustTradingPartnerCode extends UPSPricingAttributeCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, CustTradingPartnerCode);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Int64);
    CustTable   custTable;

    while select CustTradingPartnerCode from custTable
        group by CustTradingPartnerCode
    {
        ret.add(custTable.CustTradingPartnerCode);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, CustTradingPartnerCode));
    qbr.value(queryValue(_value));
}
